bank.adjectives.push(...[["active","activo","/ˈæk.tɪv/","Descreve alguém que participa ou se movimenta; active in an activity.",["She is active in the school club.","My grandfather is still active.","The students took an active role.","We need an active lifestyle."],["Ela participa activamente no clube da escola.","O meu avô ainda é activo.","Os estudantes tiveram um papel activo.","Precisamos de um estilo de vida activo."]],["affordable","acessível","/əˈfɔː.də.bəl/","Indica um preço que se pode pagar; affordable for someone.",["The course is affordable.","We need affordable housing.","This phone is more affordable.","Good education should be affordable."],["O curso tem um preço acessível.","Precisamos de habitação a preços acessíveis.","Este telefone é mais acessível.","Uma boa educação deve ser acessível."]],["ancient","antigo / da Antiguidade","/ˈeɪn.ʃənt/","Descreve algo muito antigo, especialmente de uma civilização ou época passada.",["They visited an ancient city.","This is an ancient tradition.","The museum has ancient coins.","Ancient history is fascinating."],["Eles visitaram uma cidade antiga.","Esta é uma tradição antiga.","O museu tem moedas antigas.","A história antiga é fascinante."]],["attractive","atraente","/əˈtræk.tɪv/","Descreve algo que desperta interesse ou agrada visualmente.",["The design is attractive.","She made an attractive presentation.","The town is attractive to tourists.","That is an attractive offer."],["O design é atraente.","Ela fez uma apresentação apelativa.","A cidade atrai turistas.","Essa é uma oferta atraente."]],["average","médio / normal","/ˈæv.ər.ɪdʒ/","Indica um nível comum ou resultado calculado; average score/height.",["His average score was high.","The average student needs practice.","Temperatures are above average.","What is the average cost?"],["A pontuação média dele foi alta.","O estudante comum precisa de prática.","As temperaturas estão acima da média.","Qual é o custo médio?"]],["careful","cuidadoso","/ˈkeə.fəl/","Descreve atenção para evitar erros ou perigos; careful with/about.",["Be careful with the glass.","She is careful about her work.","A careful driver checks the mirrors.","Read the instructions carefully."],["Tem cuidado com o copo.","Ela é cuidadosa com o seu trabalho.","Um condutor cuidadoso verifica os espelhos.","Lê as instruções com atenção."]],["comfortable","confortável","/ˈkʌm.fə.tə.bəl/","Descreve conforto físico ou à vontade numa situação; comfortable with/in.",["These shoes are comfortable.","I feel comfortable speaking English.","The room is warm and comfortable.","She is comfortable with the decision."],["Estes sapatos são confortáveis.","Sinto-me à vontade a falar inglês.","A sala é quente e confortável.","Ela está confortável com a decisão."]],["competitive","competitivo","/kəmˈpet.ɪ.tɪv/","Descreve vontade de vencer ou um mercado com concorrência.",["He is very competitive.","The company operates in a competitive market.","We need competitive prices.","The team has a competitive spirit."],["Ele é muito competitivo.","A empresa actua num mercado concorrencial.","Precisamos de preços competitivos.","A equipa tem espírito competitivo."]],["convenient","conveniente / prático","/kənˈviː.ni.ənt/","Indica que algo facilita a vida ou se ajusta às necessidades; convenient for.",["Online lessons are convenient for me.","Is tomorrow convenient?","The shop is in a convenient location.","This is a convenient way to pay."],["As aulas online são práticas para mim.","Amanhã é conveniente?","A loja fica num local conveniente.","Esta é uma forma prática de pagar."]],["determined","determinado","/dɪˈtɜː.mɪnd/","Descreve alguém decidido a alcançar um objectivo; determined to do something.",["She is determined to succeed.","They remained determined.","A determined learner keeps practising.","He was determined to finish the work."],["Ela está determinada a ter sucesso.","Eles mantiveram-se determinados.","Um estudante determinado continua a praticar.","Ele estava decidido a terminar o trabalho."]]]);
bank.nouns.push(...[["ability","capacidade","/əˈbɪl.ə.ti/","Capacidade de fazer algo; ability to do something.",["She has the ability to lead.","Language ability improves with practice.","He showed great ability.","The job requires the ability to communicate."],["Ela tem capacidade para liderar.","A capacidade linguística melhora com a prática.","Ele demonstrou grande capacidade.","O trabalho exige capacidade de comunicação."]],["advice","conselho","/ədˈvaɪs/","Nome incontável; usa-se a piece of advice, não an advice.",["Thank you for your advice.","Can I ask for some advice?","Her advice was useful.","He gave me a piece of advice."],["Obrigado pelo teu conselho.","Posso pedir alguns conselhos?","O conselho dela foi útil.","Ele deu-me um conselho."]],["agreement","acordo","/əˈɡriː.mənt/","Entendimento entre pessoas ou organizações; agreement with/on/about.",["They reached an agreement.","We have an agreement with the school.","The agreement starts in June.","There is broad agreement on this issue."],["Eles chegaram a um acordo.","Temos um acordo com a escola.","O acordo começa em Junho.","Há amplo consenso sobre esta questão."]],["application","candidatura / aplicação","/ˌæp.lɪˈkeɪ.ʃən/","Pode significar pedido formal ou programa informático; application for/to.",["I sent my university application.","Your application was received.","This application helps students learn.","The application deadline is Friday."],["Enviei a minha candidatura à universidade.","A tua candidatura foi recebida.","Esta aplicação ajuda os estudantes a aprender.","O prazo de candidatura termina sexta-feira."]],["behaviour","comportamento","/bɪˈheɪ.vjər/","Forma britânica; nome incontável para a maneira de agir.",["Good behaviour is important in class.","The teacher discussed his behaviour.","Stress can affect behaviour.","Children learn through observing behaviour."],["O bom comportamento é importante na aula.","O professor falou sobre o comportamento dele.","O stress pode afectar o comportamento.","As crianças aprendem observando comportamentos."]],["benefit","benefício","/ˈben.ɪ.fɪt/","Vantagem ou resultado positivo; benefit of something.",["One benefit of reading is better vocabulary.","The course offers many benefits.","Exercise has a health benefit.","We discussed the benefits of teamwork."],["Um benefício da leitura é melhorar o vocabulário.","O curso oferece muitos benefícios.","O exercício traz um benefício para a saúde.","Falámos dos benefícios do trabalho em equipa."]],["career","carreira","/kəˈrɪər/","Percurso profissional ao longo do tempo; career in/as.",["She wants a career in medicine.","He started his career as a teacher.","English can support your career.","They discussed career opportunities."],["Ela quer uma carreira na medicina.","Ele começou a carreira como professor.","O inglês pode apoiar a tua carreira.","Eles falaram de oportunidades profissionais."]],["choice","escolha","/tʃɔɪs/","Acto ou possibilidade de escolher; choice between/of.",["You have a choice.","It was a difficult choice.","We made the right choice.","There is a wide choice of courses."],["Tens uma escolha.","Foi uma escolha difícil.","Fizemos a escolha certa.","Há uma grande variedade de cursos."]],["colleague","colega de trabalho","/ˈkɒl.iːɡ/","Pessoa que trabalha contigo; colleague at/from work.",["My colleague helped me.","She is a colleague from the office.","I discussed the plan with my colleagues.","A colleague sent the email."],["O meu colega ajudou-me.","Ela é uma colega do escritório.","Falei do plano com os meus colegas.","Um colega enviou o e-mail."]],["communication","comunicação","/kəˌmjuː.nɪˈkeɪ.ʃən/","Processo de transmitir informação; communication with/between.",["Clear communication prevents mistakes.","Communication is essential in a team.","We use English for communication.","The course develops communication skills."],["Uma comunicação clara evita erros.","A comunicação é essencial numa equipa.","Usamos inglês para comunicar.","O curso desenvolve competências de comunicação."]]]);
bank.pronouns.push(...[["everybody","toda a gente","/ˈev.riˌbɒd.i/","Pronome indefinido singular; o verbo concorda normalmente no singular.",["Everybody is welcome.","Everybody knows the answer.","Is everybody ready?","Everybody has a different opinion."],["Toda a gente é bem-vinda.","Toda a gente sabe a resposta.","Está toda a gente pronta?","Cada pessoa tem uma opinião diferente."]],["everything","tudo","/ˈev.ri.θɪŋ/","Pronome indefinido singular que se refere a todas as coisas ou aspectos.",["Everything is ready.","I told her everything.","Everything depends on the weather.","He wants to learn everything."],["Está tudo pronto.","Contei-lhe tudo.","Tudo depende do tempo.","Ele quer aprender tudo."]],["something","alguma coisa / algo","/ˈsʌm.θɪŋ/","Usa-se sobretudo em frases afirmativas e ofertas ou pedidos; something to eat.",["I have something to tell you.","Would you like something to drink?","Something is wrong.","She needs something useful."],["Tenho algo para te dizer.","Gostarias de beber alguma coisa?","Há algo de errado.","Ela precisa de algo útil."]],["anything","alguma coisa / qualquer coisa / nada","/ˈen.i.θɪŋ/","Comum em perguntas e negativas; em afirmativas pode significar qualquer coisa.",["Do you need anything?","I cannot see anything.","You can ask me anything.","Is there anything I can do?"],["Precisas de alguma coisa?","Não consigo ver nada.","Podes perguntar-me qualquer coisa.","Há alguma coisa que eu possa fazer?"]],["nothing","nada","/ˈnʌθ.ɪŋ/","Pronome negativo com verbo afirmativo; não combinar com another negative in standard English.",["Nothing is impossible.","I heard nothing.","There is nothing in the box.","Nothing happened yesterday."],["Nada é impossível.","Não ouvi nada.","Não há nada na caixa.","Ontem não aconteceu nada."]],["somebody","alguém","/ˈsʌm.bɒd.i/","Pronome indefinido singular para uma pessoa não identificada; comum em afirmativas.",["Somebody is at the door.","I need somebody to help me.","Somebody called this morning.","She wants somebody to listen."],["Está alguém à porta.","Preciso de alguém para me ajudar.","Alguém telefonou esta manhã.","Ela quer alguém que a ouça."]],["anybody","alguém / qualquer pessoa / ninguém","/ˈen.iˌbɒd.i/","Usa-se em perguntas e negativas; em afirmativas significa qualquer pessoa.",["Does anybody know?","I did not see anybody.","Anybody can learn with practice.","Is anybody here?"],["Alguém sabe?","Não vi ninguém.","Qualquer pessoa pode aprender com prática.","Está alguém aqui?"]],["nobody","ninguém","/ˈnəʊ.bɒd.i/","Pronome indefinido singular negativo; o verbo fica na forma afirmativa.",["Nobody was absent.","Nobody knows the truth.","I invited nobody.","Nobody wants to fail."],["Ninguém faltou.","Ninguém sabe a verdade.","Não convidei ninguém.","Ninguém quer falhar."]],["both","ambos / os dois","/bəʊθ/","Refere-se a duas pessoas ou coisas; both of + pronome/determinante ou both + plural noun.",["Both are correct.","Both of my sisters study English.","We invited them both.","Both answers are acceptable."],["Ambos estão correctos.","As minhas duas irmãs estudam inglês.","Convidámo-los aos dois.","As duas respostas são aceitáveis."]],["all","todos / tudo","/ɔːl/","Refere-se à totalidade; all of + pronome ou all + nome plural/incontável.",["All are welcome.","All of us passed the test.","I spent all my money.","All the information is here."],["Todos são bem-vindos.","Todos nós passámos no teste.","Gastei todo o meu dinheiro.","Toda a informação está aqui."]]]);
bank.verbs.push(...[["begin","começar","/bɪˈɡɪn/","Irregular: begin – began – begun. Begin to do something ou begin doing something.",["The lesson begins at eight.","She began to study early.","They have begun a new project.","It is beginning to rain."],["A aula começa às oito.","Ela começou a estudar cedo.","Eles começaram um novo projecto.","Está a começar a chover."],"irregular"],["bring","trazer","/brɪŋ/","Irregular: bring – brought – brought. Bring something to a place/person.",["Please bring your notebook.","He brought his friend to class.","She has brought the documents.","Can you bring me some water?"],["Por favor, traz o teu caderno.","Ele trouxe o amigo para a aula.","Ela trouxe os documentos.","Podes trazer-me água?"],"irregular"],["call","telefonar / chamar","/kɔːl/","Regular: call – called – called. Call someone; call someone by a name.",["I will call you tomorrow.","She called the teacher.","They called the project a success.","He has called twice today."],["Vou telefonar-te amanhã.","Ela chamou o professor.","Eles consideraram o projecto um sucesso.","Ele já telefonou duas vezes hoje."],"regular"],["carry","transportar / carregar","/ˈkær.i/","Regular: carry – carried – carried. Carry something in/on a place.",["She carries a small bag.","They carried the boxes upstairs.","He has carried this responsibility for years.","Do not carry too much weight."],["Ela transporta uma mala pequena.","Eles levaram as caixas para cima.","Ele carrega esta responsabilidade há anos.","Não carregues demasiado peso."],"regular"],["catch","apanhar / capturar","/kætʃ/","Irregular: catch – caught – caught. Catch a bus, a ball, a cold or someone's attention.",["I catch the bus at seven.","He caught the ball.","She has caught a cold.","The headline caught my attention."],["Apanho o autocarro às sete.","Ele apanhou a bola.","Ela apanhou uma constipação.","O título chamou a minha atenção."],"irregular"],["change","mudar / alterar","/tʃeɪndʒ/","Regular: change – changed – changed. Change something; change into something.",["People can change their habits.","The weather changed suddenly.","I have changed my password.","She changed into her uniform."],["As pessoas podem mudar os seus hábitos.","O tempo mudou de repente.","Mudei a minha palavra-passe.","Ela vestiu o uniforme."],"regular"],["choose","escolher","/tʃuːz/","Irregular: choose – chose – chosen. Choose between options; choose to do something.",["Choose the correct answer.","He chose the blue shirt.","They have chosen a new leader.","You can choose to study now."],["Escolhe a resposta correcta.","Ele escolheu a camisa azul.","Eles escolheram um novo líder.","Podes optar por estudar agora."],"irregular"],["clean","limpar","/kliːn/","Regular: clean – cleaned – cleaned. Clean a place/object; clean up means tidy/remove dirt.",["I clean my room every Saturday.","She cleaned the kitchen.","They have cleaned the classroom.","Please clean up after the activity."],["Limpo o meu quarto todos os sábados.","Ela limpou a cozinha.","Eles limparam a sala de aula.","Por favor, arruma e limpa depois da actividade."],"regular"],["come","vir","/kʌm/","Irregular: come – came – come. Come to a place; come from a place.",["Come here, please.","She came late yesterday.","They have come to help us.","Where do you come from?"],["Vem aqui, por favor.","Ela veio tarde ontem.","Eles vieram ajudar-nos.","De onde és?"],"irregular"],["consider","considerar","/kənˈsɪd.ər/","Regular: consider – considered – considered. Consider + noun or verb-ing.",["We should consider every option.","She considered changing schools.","They considered the proposal carefully.","I have considered your advice."],["Devemos considerar todas as opções.","Ela ponderou mudar de escola.","Eles analisaram cuidadosamente a proposta.","Considerei o teu conselho."],"regular"]]);
bank.prepositions.push(...[["under","debaixo de / sob","/ˈʌn.dər/","Indica posição inferior, controlo ou condição; under the table, under pressure.",["The cat is under the table.","The project is under review.","She works well under pressure.","Children under twelve need a ticket."],["O gato está debaixo da mesa.","O projecto está sob análise.","Ela trabalha bem sob pressão.","As crianças com menos de doze anos precisam de bilhete."]],["over","por cima de / sobre / mais de","/ˈəʊ.vər/","Indica posição superior, movimento por cima ou quantidade superior; over 100.",["A plane flew over the city.","Put a blanket over the child.","The meeting lasted over an hour.","There is a bridge over the river."],["Um avião sobrevoou a cidade.","Põe uma manta por cima da criança.","A reunião durou mais de uma hora.","Há uma ponte sobre o rio."]],["near","perto de","/nɪər/","Indica proximidade; near the school. Também pode funcionar como adjectivo ou advérbio.",["The bank is near the market.","We live near the beach.","Do not stand near the road.","There is a pharmacy near here."],["O banco fica perto do mercado.","Vivemos perto da praia.","Não fiques perto da estrada.","Há uma farmácia aqui perto."]],["past","para além de / depois de","/pɑːst/","Indica passagem para além de um ponto ou hora posterior; walk past, past five.",["Walk past the hospital.","It is half past six.","The bus went past our house.","We are past the difficult stage."],["Passa pelo hospital e continua.","São seis e meia.","O autocarro passou pela nossa casa.","Já ultrapassámos a fase difícil."]],["per","por / cada","/pɜːr/","Usa-se em taxas, proporções e expressões formais; per person, per day.",["The fee is ten dollars per person.","She earns per hour.","The speed limit is 60 kilometres per hour.","We meet twice per week."],["A taxa é de dez dólares por pessoa.","Ela recebe à hora.","O limite de velocidade é de 60 quilómetros por hora.","Encontramo-nos duas vezes por semana."]],["since","desde","/sɪns/","Marca o ponto inicial de um período; since + momento específico, frequentemente com present perfect.",["I have lived here since 2020.","She has studied English since January.","We have been friends since childhood.","He has not called since Monday."],["Vivo aqui desde 2020.","Ela estuda inglês desde Janeiro.","Somos amigos desde a infância.","Ele não telefona desde segunda-feira."]],["until","até","/ənˈtɪl/","Indica o limite final de tempo ou situação; until + hora/evento.",["The office is open until five.","Wait here until I return.","She studied until midnight.","We cannot decide until Friday."],["O escritório está aberto até às cinco.","Espera aqui até eu voltar.","Ela estudou até à meia-noite.","Não podemos decidir antes de sexta-feira."]],["upon","sobre / após","/əˈpɒn/","Forma mais formal de on; aparece em expressões como upon arrival e once upon a time.",["Upon arrival, show your passport.","The decision depends upon the results.","Once upon a time, there was a king.","Payment is due upon delivery."],["À chegada, apresenta o passaporte.","A decisão depende dos resultados.","Era uma vez um rei.","O pagamento é devido no acto da entrega."]],["via","por via de / através de","/ˈvaɪ.ə/","Indica rota, meio ou canal utilizado para chegar a um destino ou enviar algo.",["We travelled via Lisbon.","Send the document via email.","The message was delivered via the app.","The flight goes via Madrid."],["Viajámos via Lisboa.","Envia o documento por e-mail.","A mensagem foi entregue através da aplicação.","O voo passa por Madrid."]],["without","sem","/wɪˈðaʊt/","Indica ausência de algo; é seguido de nome, pronome ou verbo-ing.",["I cannot work without my glasses.","She left without saying goodbye.","We finished the task without help.","Never leave home without your keys."],["Não consigo trabalhar sem os meus óculos.","Ela saiu sem se despedir.","Concluímos a tarefa sem ajuda.","Nunca saias de casa sem as tuas chaves."]]]);

bank.adjectives.push(... [["accurate","exacto","/ˈæk.jə.rət/","Descreve algo correcto e sem erros; accurate information or measurements.",["The report is accurate.","Please give an accurate answer.","These measurements are accurate.","The map is accurate."],["O relatório é exacto.","Por favor, dá uma resposta correcta.","Estas medições são exactas.","O mapa é rigoroso."]],["adaptable","adaptável","/əˈdæp.tə.bəl/","Descreve alguém ou algo capaz de se ajustar a novas situações.",["She is adaptable at work.","Children are often adaptable.","We need an adaptable plan.","An adaptable team learns quickly."],["Ela adapta-se bem no trabalho.","As crianças são frequentemente adaptáveis.","Precisamos de um plano adaptável.","Uma equipa adaptável aprende depressa."]],["adequate","adequado / suficiente","/ˈæd.ɪ.kwət/","Indica que algo é suficiente ou apropriado para uma finalidade.",["The room is adequate for the class.","We have adequate time.","The explanation was adequate.","Is this equipment adequate?"],["A sala é adequada para a turma.","Temos tempo suficiente.","A explicação foi adequada.","Este equipamento é suficiente?"]],["brilliant","brilhante","/ˈbrɪl.jənt/","Pode descrever inteligência, uma ideia ou um desempenho excelente.",["That is a brilliant idea.","She is a brilliant student.","He gave a brilliant performance.","The solution was brilliant."],["Essa é uma ideia brilhante.","Ela é uma estudante brilhante.","Ele teve um desempenho brilhante.","A solução foi excelente."]],["confident","confiante","/ˈkɒn.fɪ.dənt/","Usa-se frequentemente com about, in ou that para expressar confiança.",["I feel confident about the test.","She is confident in her skills.","He sounded confident.","We are confident that we can succeed."],["Sinto-me confiante em relação ao teste.","Ela confia nas suas capacidades.","Ele pareceu confiante.","Estamos confiantes de que podemos ter sucesso."]],["curious","curioso","/ˈkjʊə.ri.əs/","Descreve vontade de saber; curious about something ou curious to know.",["The child is curious about science.","I am curious to know the result.","Curious students ask questions.","She was curious about the new school."],["A criança tem curiosidade pela ciência.","Estou curioso para saber o resultado.","Os estudantes curiosos fazem perguntas.","Ela estava curiosa sobre a nova escola."]],["generous","generoso","/ˈdʒen.ər.əs/","Descreve quem partilha ou oferece mais do que o esperado.",["He is generous with his time.","That was a generous gift.","Our neighbours are generous.","She gave us a generous amount of food."],["Ele é generoso com o seu tempo.","Foi uma oferta generosa.","Os nossos vizinhos são generosos.","Ela deu-nos uma quantidade generosa de comida."]],["honest","honesto / sincero","/ˈɒn.ɪst/","Usa-se para pessoas e respostas; honest with someone ou honest about something.",["Be honest with your teacher.","She gave an honest answer.","He is honest about his mistakes.","An honest person earns trust."],["Sê honesto com o teu professor.","Ela deu uma resposta sincera.","Ele é honesto sobre os seus erros.","Uma pessoa honesta conquista confiança."]],["independent","independente","/ˌɪn.dɪˈpen.dənt/","Descreve autonomia; independent of something ou independent from someone.",["She is an independent learner.","The organisation is independent.","He became financially independent.","Children should learn to think independently."],["Ela é uma estudante autónoma.","A organização é independente.","Ele tornou-se financeiramente independente.","As crianças devem aprender a pensar de forma independente."]],["reliable","fiável","/rɪˈlaɪ.ə.bəl/","Descreve alguém ou algo em que se pode confiar; reliable source/person.",["This is a reliable source.","We need a reliable driver.","Her information is reliable.","He is a reliable friend."],["Esta é uma fonte fiável.","Precisamos de um motorista de confiança.","A informação dela é fiável.","Ele é um amigo de confiança."]]]);
bank.nouns.push(... [["achievement","conquista","/əˈtʃiːv.mənt/","Nome contável para um resultado alcançado com esforço; an achievement in something.",["Passing the exam was a great achievement.","Her achievements inspire us.","Finishing the project is an achievement.","The team celebrated its achievement."],["Passar no exame foi uma grande conquista.","As conquistas dela inspiram-nos.","Terminar o projecto é uma conquista.","A equipa celebrou a sua conquista."]],["advantage","vantagem","/ədˈvɑːn.tɪdʒ/","Nome contável; advantage of something ou advantage over someone.",["English gives you an advantage.","What is the advantage of this method?","Our team has an advantage.","Experience can be a great advantage."],["O inglês dá-te uma vantagem.","Qual é a vantagem deste método?","A nossa equipa tem uma vantagem.","A experiência pode ser uma grande vantagem."]],["appointment","marcação / compromisso","/əˈpɔɪnt.mənt/","Compromisso marcado para uma hora; make, book ou keep an appointment.",["I have a doctor's appointment.","She made an appointment for Monday.","Please arrive before your appointment.","He missed the appointment."],["Tenho uma consulta médica marcada.","Ela marcou para segunda-feira.","Por favor, chega antes da hora marcada.","Ele faltou ao compromisso."]],["attitude","atitude","/ˈæt.ɪ.tjuːd/","Forma de pensar ou agir perante alguém ou alguma coisa; attitude towards something.",["A positive attitude helps learners.","His attitude towards work changed.","We should respect different attitudes.","Her attitude was professional."],["Uma atitude positiva ajuda os estudantes.","A atitude dele perante o trabalho mudou.","Devemos respeitar atitudes diferentes.","A atitude dela foi profissional."]],["community","comunidade","/kəˈmjuː.nə.ti/","Grupo de pessoas ligadas por local, interesses ou identidade.",["The community supports the school.","Our community is growing.","They work for the local community.","Education benefits the whole community."],["A comunidade apoia a escola.","A nossa comunidade está a crescer.","Eles trabalham para a comunidade local.","A educação beneficia toda a comunidade."]],["confidence","confiança","/ˈkɒn.fɪ.dəns/","Nome incontável para segurança em si mesmo ou confiança em alguém; confidence in.",["Practice builds confidence.","She has confidence in her team.","His confidence improved.","Speaking daily gives you confidence."],["A prática desenvolve a confiança.","Ela confia na sua equipa.","A confiança dele melhorou.","Falar diariamente dá-te confiança."]],["environment","ambiente","/ɪnˈvaɪ.rən.mənt/","Pode referir-se ao meio natural ou às condições em que se aprende e trabalha.",["A clean environment is important.","The school has a safe learning environment.","We must protect the environment.","Noise affects the working environment."],["Um ambiente limpo é importante.","A escola tem um ambiente de aprendizagem seguro.","Devemos proteger o ambiente.","O ruído afecta o ambiente de trabalho."]],["experience","experiência","/ɪkˈspɪə.ri.əns/","Pode ser contável (um acontecimento) ou incontável (conhecimento adquirido).",["She has experience in teaching.","It was a wonderful experience.","Experience helps us improve.","He wants to gain work experience."],["Ela tem experiência no ensino.","Foi uma experiência maravilhosa.","A experiência ajuda-nos a melhorar.","Ele quer ganhar experiência profissional."]],["opportunity","oportunidade","/ˌɒp.əˈtjuː.nə.ti/","Ocasião favorável; opportunity to do something ou opportunity for someone.",["This is an opportunity to learn.","She found a new opportunity.","Do not miss the opportunity.","The programme creates opportunities for young people."],["Esta é uma oportunidade para aprender.","Ela encontrou uma nova oportunidade.","Não percas a oportunidade.","O programa cria oportunidades para os jovens."]],["responsibility","responsabilidade","/rɪˌspɒn.sɪˈbɪl.ə.ti/","Dever de cuidar de algo ou responder pelas próprias acções; responsibility for.",["Education is a shared responsibility.","He accepted responsibility for the mistake.","Parents have responsibilities.","It is your responsibility to study."],["A educação é uma responsabilidade partilhada.","Ele assumiu a responsabilidade pelo erro.","Os pais têm responsabilidades.","É tua responsabilidade estudar."]]]);
bank.pronouns.push(... [["herself","ela própria / si mesma","/hɜːˈself/","Pronome reflexivo ou enfático de she; sujeito e objecto referem-se à mesma pessoa.",["She taught herself to cook.","She introduced herself.","The manager herself answered.","She looked at herself in the mirror."],["Ela aprendeu a cozinhar sozinha.","Ela apresentou-se.","A própria gerente respondeu.","Ela olhou para si mesma ao espelho."]],["himself","ele próprio / si mesmo","/hɪmˈself/","Pronome reflexivo ou enfático de he; também surge em by himself.",["He hurt himself playing football.","He built the table himself.","He lives by himself.","The director himself called us."],["Ele magoou-se a jogar futebol.","Ele próprio construiu a mesa.","Ele vive sozinho.","O próprio director telefonou-nos."]],["itself","si próprio / em si","/ɪtˈself/","Pronome reflexivo de it, usado para animais, objectos, ideias e situações.",["The door closed by itself.","The machine switches itself off.","The problem itself is simple.","The cat cleaned itself."],["A porta fechou-se sozinha.","A máquina desliga-se automaticamente.","O problema em si é simples.","O gato limpou-se."]],["one another","uns aos outros","/ˌwʌn əˈnʌð.ər/","Pronome recíproco usado quando duas ou mais pessoas fazem a acção mutuamente.",["The students help one another.","We should respect one another.","They looked at one another.","The neighbours know one another."],["Os estudantes ajudam-se uns aos outros.","Devemos respeitar-nos uns aos outros.","Eles olharam uns para os outros.","Os vizinhos conhecem-se uns aos outros."]],["each other","um ao outro / uns aos outros","/ˌiːtʃ ˈʌð.ər/","Pronome recíproco muito comum para acções mútuas entre duas ou mais pessoas.",["They trust each other.","We call each other every week.","The players encouraged each other.","The two friends understand each other."],["Eles confiam um no outro.","Telefonamo-nos todas as semanas.","Os jogadores encorajaram-se uns aos outros.","Os dois amigos compreendem-se."]],["either","um ou outro / qualquer dos dois","/ˈaɪ.ðər/","Pronome/determinante para escolher entre duas alternativas; em negativas pode significar nenhum dos dois.",["Either is fine with me.","You can take either of the buses.","I do not like either.","Either answer is acceptable."],["Qualquer um dos dois serve para mim.","Podes apanhar qualquer um dos dois autocarros.","Não gosto de nenhum dos dois.","Qualquer uma das duas respostas é aceitável."]],["neither","nenhum dos dois","/ˈnaɪ.ðər/","Pronome/determinante negativo para duas opções; neither of + plural noun/pronoun.",["Neither is correct.","Neither of them called.","I like neither option.","Neither answer explains the problem."],["Nenhum dos dois está correcto.","Nenhum deles telefonou.","Não gosto de nenhuma das opções.","Nenhuma das respostas explica o problema."]],["whatever","o que quer que / qualquer coisa que","/wɒtˈev.ər/","Pronome relativo livre ou determinante; introduz uma escolha sem restrição.",["Choose whatever you prefer.","Whatever happens, stay calm.","You can ask whatever question you like.","I will support whatever decision you make."],["Escolhe o que preferires.","Aconteça o que acontecer, mantém a calma.","Podes fazer qualquer pergunta que quiseres.","Apoiarei qualquer decisão que tomares."]],["whoever","quem quer que / qualquer pessoa que","/huːˈev.ər/","Refere-se a uma pessoa não especificada; whoever comes, whoever you choose.",["Whoever arrives first can start.","Give the message to whoever answers.","Whoever studies regularly improves.","I will listen to whoever has a solution."],["Quem chegar primeiro pode começar.","Entrega a mensagem a quem responder.","Quem estuda regularmente melhora.","Vou ouvir quem tiver uma solução."]],["whatever","qualquer que seja","/wɒtˈev.ər/","Também funciona como determinante antes de um nome para indicar ausência de restrição.",["Take whatever book you need.","Whatever time you arrive is fine.","Choose whatever colour you like.","Whatever reason he gives, listen carefully."],["Leva qualquer livro de que precises.","Qualquer que seja a hora a que chegares, está bem.","Escolhe a cor que quiseres.","Qualquer que seja a razão que ele apresentar, ouve com atenção."]]]);
bank.verbs.push(... [["achieve","alcançar / conseguir","/əˈtʃiːv/","Regular: achieve – achieved – achieved. Achieve a goal, result or success.",["She achieved her goal.","We can achieve more together.","He has achieved excellent results.","They worked hard to achieve success."],["Ela alcançou o seu objectivo.","Podemos conseguir mais juntos.","Ele alcançou excelentes resultados.","Eles trabalharam muito para alcançar o sucesso."],"regular"],["advise","aconselhar","/ədˈvaɪz/","Regular: advise – advised – advised. Advise someone to do something; advise against something.",["I advise you to practise daily.","The doctor advised him to rest.","She advised against the plan.","Teachers advise students about study habits."],["Aconselho-te a praticar diariamente.","O médico aconselhou-o a descansar.","Ela desaconselhou o plano.","Os professores aconselham os alunos sobre hábitos de estudo."],"regular"],["allow","permitir","/əˈlaʊ/","Regular: allow – allowed – allowed. Allow someone to do something; be allowed to.",["My parents allow me to study.","The school allowed visitors to enter.","We are not allowed to park here.","This app allows users to practise."],["Os meus pais permitem-me estudar.","A escola permitiu a entrada de visitantes.","Não nos é permitido estacionar aqui.","Esta aplicação permite aos utilizadores praticar."],"regular"],["avoid","evitar","/əˈvɔɪd/","Regular: avoid – avoided – avoided. Avoid + noun or verb-ing, not normally to + infinitive.",["Avoid making the same mistake.","He avoided the difficult question.","We should avoid wasting time.","She avoids driving at night."],["Evita cometer o mesmo erro.","Ele evitou a pergunta difícil.","Devemos evitar desperdiçar tempo.","Ela evita conduzir à noite."],"regular"],["borrow","pedir emprestado","/ˈbɒr.əʊ/","Regular: borrow – borrowed – borrowed. Borrow something from someone; lend is the opposite.",["Can I borrow your pen?","She borrowed a book from me.","They often borrow money.","I borrowed his dictionary yesterday."],["Posso pedir a tua caneta emprestada?","Ela pediu-me um livro emprestado.","Eles pedem dinheiro emprestado frequentemente.","Ontem pedi o dicionário dele emprestado."],"regular"],["build","construir","/bɪld/","Irregular: build – built – built. Build a house, relationship, skill or habit.",["They built a new school.","We are building a strong team.","He has built his own business.","Practice builds confidence."],["Eles construíram uma nova escola.","Estamos a construir uma equipa forte.","Ele construiu o seu próprio negócio.","A prática desenvolve a confiança."],"irregular"],["deal","lidar / negociar","/diːl/","Irregular: deal – dealt – dealt. Deal with a problem; deal in a product.",["She deals with customers politely.","We must deal with this problem.","He dealt with the complaint yesterday.","The company deals in spare parts."],["Ela lida educadamente com os clientes.","Temos de lidar com este problema.","Ele tratou da reclamação ontem.","A empresa comercializa peças sobresselentes."],"irregular"],["drive","conduzir","/draɪv/","Irregular: drive – drove – driven. Drive a car; drive someone to a place.",["I drive to work every day.","She drove us to the airport.","He has driven this bus for years.","Do not drive too fast."],["Conduzo para o trabalho todos os dias.","Ela levou-nos de carro ao aeroporto.","Ele conduz este autocarro há anos.","Não conduzas demasiado depressa."],"irregular"],["feel","sentir","/fiːl/","Irregular: feel – felt – felt. Feel + adjective; feel like + noun or verb-ing.",["I feel happy today.","She felt tired after work.","We have felt the difference.","Do you feel like studying?"],["Sinto-me feliz hoje.","Ela sentiu-se cansada depois do trabalho.","Sentimos a diferença.","Apetece-te estudar?"],"irregular"],["keep","manter / guardar","/kiːp/","Irregular: keep – kept – kept. Keep something safe; keep doing something.",["Keep your documents safe.","He kept his promise.","She has kept all the letters.","Keep practising every day."],["Mantém os teus documentos em segurança.","Ele cumpriu a sua promessa.","Ela guardou todas as cartas.","Continua a praticar todos os dias."],"irregular"]]);
bank.prepositions.push(... [["beneath","por baixo de","/bɪˈniːθ/","Indica posição inferior, frequentemente com tom mais formal do que under.",["The keys are beneath the newspaper.","A river flows beneath the bridge.","The village lies beneath the mountain.","She wore a shirt beneath her jacket."],["As chaves estão por baixo do jornal.","Um rio corre por baixo da ponte.","A aldeia fica abaixo da montanha.","Ela vestia uma camisa por baixo do casaco."]],["besides","além de","/bɪˈsaɪdz/","Introduz algo adicional; besides + nome ou pronome. Não confundir com beside (ao lado).",["Besides English, he speaks French.","Besides the cost, we need to consider time.","Who came besides Ana?","Besides my brother, nobody knew."],["Além de inglês, ele fala francês.","Além do custo, precisamos de considerar o tempo.","Quem veio além da Ana?","Além do meu irmão, ninguém sabia."]],["between","entre","/bɪˈtwiːn/","Indica relação ou posição entre elementos distintos; between A and B.",["The shop is between the bank and the school.","Share the work between the two teams.","There is a difference between them.","The meeting is between nine and ten."],["A loja fica entre o banco e a escola.","Divide o trabalho entre as duas equipas.","Há uma diferença entre eles.","A reunião é entre as nove e as dez."]],["despite","apesar de","/dɪˈspaɪt/","É seguido de nome, pronome ou verbo-ing; não usar directamente uma oração com sujeito e verbo.",["Despite the rain, we went out.","She smiled despite being tired.","Despite his age, he works hard.","The match continued despite the delay."],["Apesar da chuva, saímos.","Ela sorriu apesar de estar cansada.","Apesar da idade, ele trabalha muito.","O jogo continuou apesar do atraso."]],["during","durante","/ˈdjʊə.rɪŋ/","É seguido de um nome que indica período ou acontecimento; não confundir com while + oração.",["Do not talk during the exam.","I met her during the holidays.","The lights went out during the meeting.","He slept during the journey."],["Não fales durante o exame.","Conheci-a durante as férias.","As luzes apagaram-se durante a reunião.","Ele dormiu durante a viagem."]],["inside","dentro de","/ˌɪnˈsaɪd/","Indica posição ou movimento para o interior de um espaço ou recipiente.",["The children are inside the classroom.","Put the documents inside the folder.","There is a garden inside the building.","She went inside the house."],["As crianças estão dentro da sala de aula.","Coloca os documentos dentro da pasta.","Há um jardim dentro do edifício.","Ela entrou em casa."]],["outside","fora de","/ˌaʊtˈsaɪd/","Indica posição exterior ou movimento para o exterior; outside the building.",["Wait outside the office.","The children are playing outside.","There is a car outside the house.","Smoking is not allowed outside this area."],["Espera fora do escritório.","As crianças estão a brincar lá fora.","Há um carro fora de casa.","Não é permitido fumar fora desta área."]],["through","através de","/θruː/","Indica passagem de um lado ao outro de um espaço, meio ou processo.",["We walked through the tunnel.","Light came through the window.","She learned English through practice.","The train passed through the city."],["Atravessámos o túnel a pé.","A luz entrou pela janela.","Ela aprendeu inglês através da prática.","O comboio passou pela cidade."]],["throughout","ao longo de / durante todo","/θruːˈaʊt/","Indica algo que acontece em todo um espaço ou durante todo um período.",["It rained throughout the night.","The rule applies throughout the country.","He remained calm throughout the interview.","The museum is famous throughout Europe."],["Choveu durante toda a noite.","A regra aplica-se em todo o país.","Ele manteve a calma durante toda a entrevista.","O museu é famoso em toda a Europa."]],["within","dentro de / no prazo de","/wɪˈðɪn/","Indica limite espacial, temporal ou de capacidade; within an hour, within the area.",["Please reply within two days.","The school is within walking distance.","Keep the work within the budget.","The answer is within the text."],["Por favor, responde no prazo de dois dias.","A escola fica a uma distância que se pode percorrer a pé.","Mantém o trabalho dentro do orçamento.","A resposta está no texto."]]]);

