bank.pronouns.push(...[["another","outro / mais um","/əˈnʌð.ər/","Pronome ou determinante para uma pessoa/coisa adicional ou diferente.",["This answer is wrong; try another.","I need another.","Another has already arrived.","Would you like another?"],["Esta resposta está errada; tenta outra.","Preciso de outro.","Outro já chegou.","Queres mais um?"]],["others","outros / outras","/ˈʌð.ərz/","Pronome plural que substitui nomes já conhecidos; não leva nome imediatamente depois.",["Some students arrived; others stayed home.","I respect others.","These books are old; the others are new.","Help others when you can."],["Alguns alunos chegaram; outros ficaram em casa.","Respeito os outros.","Estes livros são antigos; os outros são novos.","Ajuda os outros quando puderes."]],["the other","o outro / a outra","/ðiː ˈʌð.ər/","Refere-se ao segundo elemento de um par ou a um elemento específico.",["One shoe is here; the other is missing.","I prefer the other.","The other was more expensive.","She spoke to the other student."],["Um sapato está aqui; o outro desapareceu.","Prefiro o outro.","O outro era mais caro.","Ela falou com o outro aluno."]],["the others","os outros / as outras","/ðiː ˈʌð.ərz/","Pronome plural definido para os restantes elementos de um grupo conhecido.",["Three players arrived; the others are late.","The others agreed with us.","I will tell the others.","Where are the others?"],["Três jogadores chegaram; os outros estão atrasados.","Os outros concordaram connosco.","Vou avisar os outros.","Onde estão os outros?"]],["one","um / uma / alguém","/wʌn/","Pode substituir um nome contável ou funcionar como pronome impessoal.",["I need one.","One must practise regularly.","This one is better.","One of my friends speaks English."],["Preciso de um.","É preciso praticar regularmente.","Este é melhor.","Um dos meus amigos fala inglês."]],["ones","os / as (substitui nomes no plural)","/wʌnz/","Forma plural de one, usada para evitar repetir um nome contável.",["The red ones are mine.","Choose the smaller ones.","I prefer these ones.","New ones will arrive tomorrow."],["Os vermelhos são meus.","Escolhe os mais pequenos.","Prefiro estes.","Novos chegarão amanhã."]],["some","alguns / algumas / um pouco","/sʌm/","Pronome indefinido usado para quantidade não especificada, sobretudo em afirmativas.",["Some are ready.","Would you like some?","I bought some yesterday.","Some of them speak French."],["Alguns estão prontos.","Queres um pouco?","Comprei alguns ontem.","Alguns deles falam francês."]],["any","algum / qualquer / nenhum","/ˈen.i/","Pronome/determinante em perguntas e negativas; em afirmativas pode significar qualquer.",["Do you have any?","I don't need any.","Choose any you like.","Are any of them available?"],["Tens algum?","Não preciso de nenhum.","Escolhe qualquer um de que gostes.","Algum deles está disponível?"]],["none","nenhum / nenhuma","/nʌn/","Pronome que significa zero elementos de um conjunto; none of + grupo.",["None of the answers is correct.","I invited five, but none came.","None is missing.","None of us was late."],["Nenhuma das respostas está correcta.","Convidei cinco, mas nenhum veio.","Nenhum está em falta.","Nenhum de nós chegou atrasado."]],["such","tal / tais","/sʌtʃ/","Pode funcionar como pronome ou determinante para indicar tipo ou grau.",["I have never seen such.","Such is the result.","We need such support.","I admire such people."],["Nunca vi algo assim.","Esse é o resultado.","Precisamos de tal apoio.","Admiro pessoas assim."]]]);
bank.verbs.push(...[["buy","comprar","/baɪ/","Irregular: buy – bought – bought. Buy something from a shop.",["I buy fresh fruit every week.","She bought a new dictionary.","They have bought the tickets.","We buy books online."],["Compro fruta fresca todas as semanas.","Ela comprou um dicionário novo.","Eles compraram os bilhetes.","Compramos livros online."],"irregular"],["cut","cortar","/kʌt/","Irregular: cut – cut – cut. Cut something into pieces.",["Cut the paper carefully.","He cut the bread yesterday.","She has cut the fabric.","They cut costs every year."],["Corta o papel com cuidado.","Ele cortou o pão ontem.","Ela cortou o tecido.","Eles reduzem os custos todos os anos."],"irregular"],["do","fazer","/duː/","Irregular: do – did – done. Do homework, work or an activity.",["I do my homework after school.","She did the exercise yesterday.","We have done our best.","What do you do at weekends?"],["Faço os trabalhos de casa depois da escola.","Ela fez o exercício ontem.","Fizemos o nosso melhor.","O que fazes aos fins-de-semana?"],"irregular"],["eat","comer","/iːt/","Irregular: eat – ate – eaten. Eat a meal or eat something.",["We eat breakfast at seven.","He ate an apple.","They have eaten already.","I eat vegetables every day."],["Tomamos o pequeno-almoço às sete.","Ele comeu uma maçã.","Eles já comeram.","Como vegetais todos os dias."],"irregular"],["find","encontrar","/faɪnd/","Irregular: find – found – found. Find an answer, object or solution.",["I find this lesson useful.","She found her keys.","We have found a solution.","They find English interesting."],["Considero esta aula útil.","Ela encontrou as chaves.","Encontrámos uma solução.","Eles acham o inglês interessante."],"irregular"],["give","dar","/ɡɪv/","Irregular: give – gave – given. Give something to someone; give someone something.",["Please give me the book.","He gave her good advice.","They have given us time.","I give lessons every week."],["Por favor, dá-me o livro.","Ele deu-lhe bons conselhos.","Eles deram-nos tempo.","Dou aulas todas as semanas."],"irregular"],["go","ir","/ɡəʊ/","Irregular: go – went – gone. Go to a place; go home (sem to).",["I go to school by bus.","She went to the market.","He has gone home.","We go there every Sunday."],["Vou para a escola de autocarro.","Ela foi ao mercado.","Ele foi para casa.","Vamos lá todos os domingos."],"irregular"],["know","saber / conhecer","/nəʊ/","Irregular: know – knew – known. Know a fact or know a person.",["I know the answer.","She knew his name.","We have known them for years.","Do you know this place?"],["Sei a resposta.","Ela sabia o nome dele.","Conhecemo-los há anos.","Conheces este lugar?"],"irregular"],["make","fazer / criar","/meɪk/","Irregular: make – made – made. Make a decision, plan or object.",["I make a list every morning.","He made a serious mistake.","They have made progress.","We make plans together."],["Faço uma lista todas as manhãs.","Ele cometeu um erro grave.","Eles fizeram progressos.","Fazemos planos juntos."],"irregular"],["read","ler","/riːd/","Irregular: read – read – read (a forma escrita é igual; a pronúncia do passado muda).",["I read the news every day.","She read the letter yesterday.","We have read that book.","They read English stories aloud."],["Leio as notícias todos os dias.","Ela leu a carta ontem.","Já lemos esse livro.","Eles lêem histórias inglesas em voz alta."],"irregular"]]);
bank.prepositions.push(...[["about","sobre / acerca de","/əˈbaʊt/","Introduz o assunto de que se fala ou escreve; talk/think/read about.",["We talked about the lesson.","This book is about history.","She is worried about the test.","Tell me about your plans."],["Falámos sobre a aula.","Este livro é sobre história.","Ela está preocupada com o teste.","Fala-me dos teus planos."]],["after","depois de","/ˈɑːf.tər/","Indica posterioridade no tempo ou no espaço; after + nome ou -ing.",["We met after class.","Wash your hands after eating.","He arrived after me.","After the meeting, we went home."],["Encontrámo-nos depois da aula.","Lava as mãos depois de comer.","Ele chegou depois de mim.","Depois da reunião, fomos para casa."]],["before","antes de","/bɪˈfɔːr/","Indica anterioridade; before + nome, pronome ou -ing.",["Finish your work before lunch.","Think before answering.","I arrived before her.","We spoke before the exam."],["Termina o teu trabalho antes do almoço.","Pensa antes de responder.","Cheguei antes dela.","Falámos antes do exame."]],["by","por / junto de / até","/baɪ/","Pode indicar agente na voz passiva, proximidade ou prazo limite.",["The book was written by her.","Sit by the window.","Finish this by Friday.","We travelled by bus."],["O livro foi escrito por ela.","Senta-te junto à janela.","Termina isto até sexta-feira.","Viajámos de autocarro."]],["for","para / por / durante","/fɔːr/","Indica finalidade, destinatário, duração ou motivo.",["This gift is for you.","I studied for two hours.","Thank you for your help.","We left for the airport."],["Este presente é para ti.","Estudei durante duas horas.","Obrigado pela tua ajuda.","Partimos para o aeroporto."]],["from","de / desde","/frɒm/","Indica origem, ponto de partida ou separação; from ... to ...",["She is from Angola.","The train leaves from platform two.","I work from Monday to Friday.","This message is from my teacher."],["Ela é de Angola.","O comboio parte da plataforma dois.","Trabalho de segunda a sexta-feira.","Esta mensagem é do meu professor."]],["into","para dentro de / em","/ˈɪn.tuː/","Indica movimento para o interior ou transformação; go/get into.",["She walked into the room.","Put the books into the bag.","Water turned into ice.","He got into the car."],["Ela entrou na sala.","Põe os livros dentro da mala.","A água transformou-se em gelo.","Ele entrou no carro."]],["off","de / para fora de","/ɒf/","Indica afastamento de uma superfície ou separação; take off, get off.",["Take your shoes off.","The cup fell off the table.","We got off the bus.","Keep off the grass."],["Tira os sapatos.","A chávena caiu da mesa.","Saímos do autocarro.","Não pises a relva."]],["on","em / sobre / ligado a","/ɒn/","Indica contacto com uma superfície, dias/datas e funcionamento.",["The keys are on the desk.","The meeting is on Monday.","Turn the light on.","There is a picture on the wall."],["As chaves estão sobre a secretária.","A reunião é na segunda-feira.","Liga a luz.","Há um quadro na parede."]],["onto","para cima de","/ˈɒn.tuː/","Indica movimento para uma superfície; distingue-se de on, que indica posição.",["The cat jumped onto the chair.","Put the papers onto the table.","He climbed onto the roof.","Move the box onto the shelf."],["O gato saltou para cima da cadeira.","Põe os papéis sobre a mesa.","Ele subiu para o telhado.","Move a caixa para cima da prateleira."]]]);
